{"command":"$files = Get-ChildItem -Path 'Script/Blueprint/Prefabs/Monsters/MainScene' -Recurse -Filter 'BaseMons*.lua'
$old = "    DisableMonsterCollision(self)`r`n`r`n    if self:HasAuthority() then"
$new = "    DisableMonsterCollision(self)`r`n`r`n    if self:HasAuthority() and self.SpawnWall ~= nil then`r`n        self.SpawnWall:OnMonsterDied(self)`r`n    end`r`n`r`n    if self:HasAuthority() then"
$changed = 0
foreach ($file in $files) {
    $path = $file.FullName
    $text = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)
    if ($text -match 'SpawnWall:OnMonsterDied') { continue }
    if ($text.Contains($old)) {
        $text = $text.Replace($old, $new)
        [System.IO.File]::WriteAllText($path, $text, [System.Text.UTF8Encoding]::new($false))
        $changed++
    } else {
        Write-Output "No match: $path"
    }
}
